// ***************
// Filename: py_stream_port_regs_if.sv
// Author: FPGA Cores 4 U
// Description: Register interface of py_stream_port: joins the register map
//   py_stream_port_regs (modport regs) and the logic py_stream_port (modport
//   core). cfg_* go from the register map to the logic (register values, _wr
//   write pulses, _rd read pulses), sts_* come back (values read, _set / _clr
//   hardware set / clear pulses). A logic block ties every sts_* member it
//   does not use to 0. Generated by ip/scripts/regmap_gen.py from
//   py_stream_port_regs.json: edit the JSON and regenerate.
// Date: 2026-10-16
interface py_stream_port_regs_if ();
  logic [25-1:0] cfg_txdata;
  logic cfg_txdata_wr;
  logic [32-1:0] sts_rxdata;
  logic cfg_rxdata_rd;
  logic [32-1:0] sts_status;
  logic [32-1:0] cfg_status;
  logic cfg_status_wr;
  logic [3-1:0] cfg_irq_en;
  logic cfg_irq_en_wr;

  modport regs (output cfg_txdata, cfg_txdata_wr, cfg_rxdata_rd, cfg_status, cfg_status_wr, cfg_irq_en,
    cfg_irq_en_wr, input sts_rxdata, sts_status);
  modport core (output sts_rxdata, sts_status, input cfg_txdata, cfg_txdata_wr, cfg_rxdata_rd, cfg_status,
    cfg_status_wr, cfg_irq_en, cfg_irq_en_wr);
  modport monitor (input cfg_txdata, cfg_txdata_wr, cfg_rxdata_rd, cfg_status, cfg_status_wr, cfg_irq_en,
    cfg_irq_en_wr, sts_rxdata, sts_status);
endinterface
